"""Static game data, loaded from data/locations.json (generated by tools/gen_data.py)."""
from __future__ import annotations

import json
import pkgutil
from typing import Any, Dict, List, NamedTuple, Optional

ITEM_BASE_ID = 0xD05C_0000

_raw: Dict[str, Any] = json.loads(pkgutil.get_data(__name__, "data/locations.json").decode("utf-8"))


class LevelData(NamedTuple):
    code: str          # "E1M6" (in-game numbering)
    scene: str         # "E1M5AndAHalf" (Unity scene name)
    name: str          # "The Cutty Mine"
    episode: int
    secret: bool
    keys: List[str]    # ["Red Key", "Yellow Key"]

    @property
    def number(self) -> int:
        """Level number within the episode; secret levels sort last."""
        return 99 if self.secret else int(self.code.split("M")[1])


class LocationData(NamedTuple):
    id: int
    name: str
    level: str
    category: str
    vanilla_item: Optional[str]


LEVELS: List[LevelData] = [
    LevelData(l["code"], l["scene"], l["name"], l["episode"], l["secret"], l["keys"]) for l in _raw["levels"]
]
LEVELS_BY_CODE: Dict[str, LevelData] = {l.code: l for l in LEVELS}
LOCATIONS: List[LocationData] = [
    LocationData(l["id"], l["name"], l["level"], l["category"], l["vanilla_item"]) for l in _raw["locations"]
]

# The last (boss) level of each episode.
BOSS_LEVELS = {1: "E1M10", 2: "E2M10", 3: "E3M10"}

# Location categories that the player can toggle on and off.
CATEGORIES = ["weapons", "keys", "powerups", "secrets", "treasure_chests", "health", "armor", "ammo"]
# Always randomized: one check per level for finishing it.
ALWAYS_CATEGORIES = ["level_complete"]

# Thermal Suits are timed traversal tools that the level layouts rely on (like the respawning
# climbing powerups, which are not locations at all), so they stay vanilla.
VANILLA_ONLY_ITEMS = {"Thermal Suit"}
